// Fonction pour configurer les événements de la fenêtre flottante
function setupListFloatingWindowEvents(floatingWindow) {
  const closeBtn = floatingWindow.querySelector('#closeListBtn');
  const statusDiv = floatingWindow.querySelector('#listStatus');
  const saveConfigBtn = floatingWindow.querySelector('#saveListConfigBtn');
  const secretKeyInput = floatingWindow.querySelector('#secretKeyListInput');
  const listNameSelect = floatingWindow.querySelector('#listNameSelect');
  const configSection = floatingWindow.querySelector('#listConfigSection');
  const exportSection = floatingWindow.querySelector('#listExportSection');
  const maxCompaniesInput = floatingWindow.querySelector('#maxCompaniesInput');
  const extractCompaniesBtn = floatingWindow.querySelector('#extractCompaniesBtn');
  const addToListCheckbox = floatingWindow.querySelector('#addToListCheckbox');
  const addToListDropdownWrap = floatingWindow.querySelector('#addToListDropdownWrap');

  let listsLoaded = false;
  let isExtracting = false;
  let currentStatusInterval = null;
  let activeResponseHandler = null;
  let activeResponseTimeout = null;

  function setActiveResponseHandler(handler) {
    if (activeResponseHandler && activeResponseHandler !== handler) {
      window.removeEventListener('message', activeResponseHandler);
    }

    activeResponseHandler = handler;
    window.addEventListener('message', handler);
  }

  function removeActiveResponseHandler(handler = null) {
    if (!activeResponseHandler) {
      return;
    }

    if (handler && activeResponseHandler !== handler) {
      return;
    }

    window.removeEventListener('message', activeResponseHandler);
    activeResponseHandler = null;
  }

  function showStatus(message, type = '', useInnerHTML = false) {
    // Gestion spéciale pour le type 'processing' (comme floating-window.js)
    if (type === 'processing') {
      const i18n = window.TotleadsI18n;
      const warningMessage = i18n.t('status.processingWarning');
      const formattedWarning = warningMessage.replace(/\n/g, '<br>');
      statusDiv.innerHTML = `<div class="processing-warning">${formattedWarning}</div>`;
      statusDiv.className = 'status processing';
      statusDiv.style.display = 'block';
      return;
    }

    if (!message || (typeof message === 'string' && message.trim() === '')) {
      statusDiv.style.display = 'none';
      return;
    }

    if (useInnerHTML) {
      statusDiv.innerHTML = message;
    } else {
      statusDiv.textContent = message;
    }
    statusDiv.className = `status ${type}`;
    statusDiv.style.display = 'block';
  }

  function setConfigButtonLoading(button, loading) {
    const i18n = window.TotleadsI18n;
    button.disabled = loading;
    if (loading) {
      button.textContent = i18n.t('status.validating');
    } else {
      button.textContent = i18n.t('config.saveButton');
    }
  }

  function setButtonToStopMode(button, isStopMode) {
    const i18n = window.TotleadsI18n;
    if (isStopMode) {
      button.textContent = i18n.t('extraction.stopButton');
      button.disabled = false;
      button.style.display = 'block';
      button.classList.add('stop-mode');
    } else {
      button.textContent = i18n.t('listWindow.exportToCsvButton');
      button.disabled = false;
      button.style.display = 'block';
      button.classList.remove('stop-mode');
    }
  }

  // Met à jour le max de l'input companies à partir du quota serveur et du total API LinkedIn
  function updateMaxCompaniesFromQuota(listQuota) {
    const apiTotal = window.__totleads_account_search_total;
    let effectiveMaxUsed = null;
    if (typeof listQuota === 'number' && listQuota >= 0) {
      const effectiveMax = (typeof apiTotal === 'number' && apiTotal >= 0)
        ? Math.min(listQuota, apiTotal)
        : listQuota;
      maxCompaniesInput.max = effectiveMax;
      maxCompaniesInput.value = effectiveMax;
      effectiveMaxUsed = effectiveMax;
    } else if (typeof apiTotal === 'number' && apiTotal >= 0) {
      maxCompaniesInput.max = apiTotal;
      maxCompaniesInput.value = apiTotal;
      effectiveMaxUsed = apiTotal;
    }
    // [Totleads][diag] Tracer la borne réellement appliquée au champ "Max empresas"
    const diagPayload = {
      listQuota,
      apiTotal,
      maxApplique: effectiveMaxUsed,
      urlPage: window.location.href.slice(0, 200),
      captures: window.__totleads_account_search_log || []
    };
    console.log('[Totleads][diag] champ Max lié', diagPayload);
    // Log serveur (visible dans le fichier de log par client, sans console navigateur)
    sendDiagBeacon('account_max_bind', diagPayload);
  }

  // Vérifier si la configuration existe déjà dans localStorage
  async function checkExistingConfig() {
    const credentialService = window.TotleadsCredentialService;

    try {
      if (credentialService && credentialService.hasValidCredentials()) {
        const credentials = credentialService.getCredentials();

        if (credentials && credentials.secretKey) {
          // Vérification proactive du token à l'ouverture : ne pas afficher l'export si session morte
          const token = await credentialService.getValidSanctumToken();
          if (!token) {
            configSection.style.display = 'block';
            exportSection.style.display = 'none';
            return;
          }

          secretKeyInput.value = credentials.secretKey;
          configSection.style.display = 'none';
          exportSection.style.display = 'block';

          // Récupérer le quota via l'API pour mettre à jour le max
          try {
            const quotaService = window.TotleadsQuotaService;
            if (quotaService) {
              const quotaResult = await quotaService.fetchQuotaFromAPI(
                await window.TotleadsCredentialService.getValidSanctumToken()
              );
              if (quotaResult.success) {
                updateMaxCompaniesFromQuota(quotaResult.available_list_quota);
              }
            }
          } catch (e) {
            // Erreur silencieuse - garder les valeurs par défaut
          }

          // Charger les listes disponibles (pour le dropdown quand checkbox cochée)
          loadLists();
        }
      }
    } catch (error) {
      if (credentialService) {
        credentialService.clearCredentials();
      }
    }
  }

  // Fonction pour valider les credentials via background script
  async function validateCredentials(secretKey) {
    try {
      const response = await chrome.runtime.sendMessage({
        action: 'validateCredentials',
        secretKey: secretKey
      });

      return response;
    } catch (error) {
      return { valid: false, error: i18n.t('errors.apiConnectionError') };
    }
  }

  // Fonction pour charger les listes depuis le cache ou simuler un clic
  async function loadLists() {
    const i18n = window.TotleadsI18n;
    const config = window.TotleadsConfig;
    const CACHE_MAX_AGE = 6 * 60 * 60 * 1000; // 6 heures en millisecondes

    if (listsLoaded) {
      return;
    }

    try {
      // Vérifier si les listes sont déjà en cache
      const response = await chrome.runtime.sendMessage({
        action: config.actions.GET_LISTS_DATA
      });

      if (response.success && response.data && response.data.lists && response.data.lists.length > 0) {
        // Vérifier l'âge du cache
        const cacheTimestamp = response.data.timestamp || 0;
        const cacheAge = Date.now() - cacheTimestamp;
        const isCacheExpired = cacheAge > CACHE_MAX_AGE;

        if (!isCacheExpired) {
          // Cache valide, utiliser les listes en cache
          populateListsDropdown(response.data.lists);
          listsLoaded = true;
          return;
        }
        // Cache expiré, continuer pour recharger les listes
      }

      // Sauvegarder le cache existant pour le restaurer en cas de résultat vide
      const previousCache = response.success && response.data ? response.data : null;

      // Pas de cache ou cache expiré, simuler le clic sur le bouton "Save to list"
      showStatus(i18n.t('listWindow.loadingLists'));
      listNameSelect.disabled = true;

      const success = await simulateSaveToListClick();

      if (success) {
        // Attendre un peu que les listes soient capturées
        await new Promise(resolve => setTimeout(resolve, 2000));

        // Récupérer les listes capturées
        const listsResponse = await chrome.runtime.sendMessage({
          action: config.actions.GET_LISTS_DATA
        });

        // Vérifier si on a des listes valides
        const hasValidLists = listsResponse.success &&
          listsResponse.data &&
          listsResponse.data.lists &&
          Array.isArray(listsResponse.data.lists) &&
          listsResponse.data.lists.length > 0;

        if (hasValidLists) {
          populateListsDropdown(listsResponse.data.lists);
          listsLoaded = true;
          showStatus('', '');
        } else {
          // Aucune liste obtenue, restaurer le cache précédent s'il existe
          if (previousCache && previousCache.lists && previousCache.lists.length > 0) {
            // Restaurer l'ancien cache
            await chrome.runtime.sendMessage({
              action: 'listsDataCaptured',
              data: previousCache
            });

            populateListsDropdown(previousCache.lists);
            listsLoaded = true;
            showStatus('', '');
          } else {
            // Pas d'ancien cache, afficher un message d'erreur
            showStatus(i18n.t('errors.listsNotLoaded'), 'error');
            listNameSelect.innerHTML = `<option value="">${i18n.t('listWindow.noListsAvailable')}</option>`;
          }
        }
      } else {
        // Échec de la simulation, restaurer le cache précédent s'il existe
        if (previousCache && previousCache.lists && previousCache.lists.length > 0) {
          await chrome.runtime.sendMessage({
            action: 'listsDataCaptured',
            data: previousCache
          });

          populateListsDropdown(previousCache.lists);
          listsLoaded = true;
          showStatus('', '');
        } else {
          showStatus(i18n.t('errors.listsNotLoaded'), 'error');
          listNameSelect.innerHTML = `<option value="">${i18n.t('listWindow.noListsAvailable')}</option>`;
        }
      }

      listNameSelect.disabled = false;
    } catch (error) {
      showStatus(i18n.t('errors.listsNotLoaded'), 'error');
      listNameSelect.innerHTML = `<option value="">${i18n.t('listWindow.noListsAvailable')}</option>`;
      listNameSelect.disabled = false;
    }
  }

  // Fonction pour simuler le clic sur le bouton "Save to list" de LinkedIn
  async function simulateSaveToListClick() {
    const config = window.TotleadsConfig;
    const domHelpers = window.TotleadsDOMHelpers;

    try {
      // Étape 1 : Trouver et cliquer sur la checkbox "Select All"
      const selectAllCheckbox = await domHelpers.waitForElement(
        config.selectors.MULTI_SELECT_CHECKBOX,
        config.timeouts.ELEMENT_WAIT
      );

      if (!selectAllCheckbox) {
        return false;
      }

      // Cliquer sur la checkbox si elle n'est pas déjà cochée
      if (!selectAllCheckbox.checked) {
        selectAllCheckbox.click();
      }

      // Attendre un peu après le clic sur la checkbox
      await new Promise(resolve => setTimeout(resolve, 1000));

      // Étape 2 : Trouver et cliquer sur le bouton "Save to list"
      let saveButton = await domHelpers.waitForElement(
        config.selectors.SAVE_TO_LIST_BUTTON,
        config.timeouts.ELEMENT_WAIT
      );

      if (!saveButton) {
        return false;
      }

      // Si le bouton est désactivé, réessayer de cliquer sur Select All jusqu'à activation (jusqu'à 10s, pas plus)
      const enableDeadline = Date.now() + 10000; // 10 secondes max
      let enableAttempt = 0;
      while ((saveButton.disabled || saveButton.getAttribute('aria-disabled') === 'true') && Date.now() < enableDeadline) {
        enableAttempt++;
        if (!selectAllCheckbox.checked) {
          selectAllCheckbox.click();
        } else {
          // toggle off/on pour forcer le rafraîchissement si nécessaire
          selectAllCheckbox.click();
          await new Promise(resolve => setTimeout(resolve, 200));
          selectAllCheckbox.click();
        }
        // Attente d'1 seconde entre les tentatives pour laisser le DOM/LinkedIn réagir
        await new Promise(resolve => setTimeout(resolve, 1000));
        // Re-récupérer le bouton pour actualiser l'état
        saveButton = document.querySelector(config.selectors.SAVE_TO_LIST_BUTTON);
        if (!saveButton) {
          saveButton = await domHelpers.waitForElement(
            config.selectors.SAVE_TO_LIST_BUTTON,
            1000
          );
        }
      }

      if (saveButton.disabled || saveButton.getAttribute('aria-disabled') === 'true') {
        return false;
      }

      // Simuler le clic sur Save to list
      saveButton.click();

      // Attendre un peu que le dropdown s'ouvre et que l'API soit appelée
      await new Promise(resolve => setTimeout(resolve, 1000));

      // Vérifier que le dropdown est ouvert
      const dropdown = await domHelpers.waitForElement(
        config.selectors.LIST_DROPDOWN_MENU,
        config.timeouts.ELEMENT_WAIT
      );

      if (dropdown) {
        // Recliquer pour fermer le dropdown
        saveButton.click();
      }

      return true;
    } catch (error) {
      return false;
    }
  }

  // Fonction pour peupler le dropdown avec les listes
  function populateListsDropdown(lists) {
    const i18n = window.TotleadsI18n;

    // Vider le select
    listNameSelect.innerHTML = '';

    // Ajouter l'option par défaut
    const defaultOption = document.createElement('option');
    defaultOption.value = '';
    defaultOption.textContent = i18n.t('listWindow.selectListPlaceholder');
    listNameSelect.appendChild(defaultOption);

    // Ajouter chaque liste
    lists.forEach(list => {
      const option = document.createElement('option');
      option.value = list.name;
      option.textContent = `${list.name}`; // (${list.entityCount} items)`;
      listNameSelect.appendChild(option);
    });
  }

  // Fonction pour rafraîchir les listes
  // Bouton de sauvegarde de configuration
  saveConfigBtn.addEventListener('click', async function () {
    const i18n = window.TotleadsI18n;
    const secretKey = secretKeyInput.value.trim();

    if (!secretKey) {
      showStatus(i18n.t('errors.secretKeyRequired'), 'error');
      secretKeyInput.focus();
      return;
    }

    setConfigButtonLoading(saveConfigBtn, true);
    showStatus(i18n.t('status.validating'));

    try {
      const validation = await validateCredentials(secretKey);

      if (validation.valid) {
        const credentialService = window.TotleadsCredentialService;
        if (credentialService) {
          credentialService.saveCredentials(secretKey, validation.token);
        }

        setConfigButtonLoading(saveConfigBtn, false);
        showStatus(i18n.t('status.validated'), 'success');

        configSection.style.display = 'none';
        exportSection.style.display = 'block';

        // Charger les listes disponibles (pour le dropdown quand checkbox cochée)
        loadLists();
        
        // Gérer le quota pour l'export via /api/quota
        try {
          const quotaService = window.TotleadsQuotaService;
          if (quotaService) {
            const quotaResult = await quotaService.fetchQuotaFromAPI(validation.token);
            if (quotaResult.success) {
              updateMaxCompaniesFromQuota(quotaResult.available_list_quota);
            }
          }
        } catch (e) {
          // Erreur silencieuse
        }
      } else {
        setConfigButtonLoading(saveConfigBtn, false);
        showStatus(i18n.t('errors.validationError', { error: validation.error }), 'error');
      }
    } catch (error) {
      setConfigButtonLoading(saveConfigBtn, false);
      showStatus(i18n.t('errors.validationError', { error: error.message }), 'error');
    }
  });

  // Checkbox "Ajouter les résultats à une liste" : afficher/masquer le dropdown
  addToListCheckbox.addEventListener('change', function () {
    addToListDropdownWrap.style.display = addToListCheckbox.checked ? 'block' : 'none';
  });

  // Mode design: forcer l'état "extraction terminée" ou "extraction en cours" permanent (comme floating-window.js)
  const totleadsConfig = window.TotleadsConfig;
  const forceCompleted = totleadsConfig && totleadsConfig.FORCE_LIST_EXTRACTION_COMPLETED_UI;
  const forceProcessing = totleadsConfig && totleadsConfig.FORCE_LIST_EXTRACTION_UI;
  if (forceCompleted) {
    configSection.style.display = 'none';
    exportSection.style.display = 'block';
    showUploadSuccessForCompanies({ remaining_quota: 45, duplicatesRemoved: 5 });
  } else if (forceProcessing) {
    configSection.style.display = 'none';
    exportSection.style.display = 'block';
    isExtracting = true;
    setButtonToStopMode(extractCompaniesBtn, true);
    showStatus('', 'processing');
  }

  // Vérifier la configuration existante au chargement (sauf en mode design forcé)
  if (!forceCompleted && !forceProcessing) {
    checkExistingConfig();
  }

  // Écouter les captures API pour mettre à jour automatiquement les listes
  const config = window.TotleadsConfig;
  const handleListsMessage = async (event) => {
    if (event.source !== window) return;

    // Si on capture de nouvelles listes ou une liste créée à la volée, mettre à jour le dropdown
    if (event.data.type === config.messages.LINKEDIN_LISTS_CAPTURED ||
        event.data.type === config.messages.LINKEDIN_LISTS_UPDATED) {
      try {
        // Attendre un peu que le cache soit mis à jour dans background.js
        await new Promise(resolve => setTimeout(resolve, 500));

        // Récupérer les listes depuis le cache
        const listsResponse = await chrome.runtime.sendMessage({
          action: config.actions.GET_LISTS_DATA
        });

        // Vérifier si on a des listes valides
        if (listsResponse.success &&
          listsResponse.data &&
          listsResponse.data.lists &&
          Array.isArray(listsResponse.data.lists) &&
          listsResponse.data.lists.length > 0) {
          // Mettre à jour le dropdown avec les listes
          populateListsDropdown(listsResponse.data.lists);
          listsLoaded = true;

          // Si le select était désactivé, le réactiver
          if (listNameSelect.disabled) {
            listNameSelect.disabled = false;
          }

          // Masquer le statut de chargement s'il était affiché
          showStatus('', '');
        }
      } catch (error) {
        // Erreur silencieuse
      }
    }
  };
  window.addEventListener('message', handleListsMessage);

  // Bouton d'extraction CSV des companies
  extractCompaniesBtn.addEventListener('click', async function () {
    const i18n = window.TotleadsI18n;

    // Si on est en mode stop, arrêter l'extraction
    if (isExtracting) {
      try {
        const result = await chrome.runtime.sendMessage({
          action: 'stopAndReturnLeads'
        });

        if (currentStatusInterval) {
          clearInterval(currentStatusInterval);
          currentStatusInterval = null;
        }

        isExtracting = false;
        extractCompaniesBtn.textContent = i18n.t('listWindow.exportToCsvButton');
        extractCompaniesBtn.classList.remove('stop-mode');

        if (result && result.success && result.leadsCount > 0) {
          showStoppedStatusForCompanies(result.leadsCount, result.leads);
        } else {
          showStatus(i18n.t('status.stoppedWithZero'), 'error');
        }
      } catch (error) {
        showStatus(i18n.t('errors.stopError'), 'error');
        isExtracting = false;
        extractCompaniesBtn.textContent = i18n.t('listWindow.exportToCsvButton');
        extractCompaniesBtn.classList.remove('stop-mode');
      }
      return;
    }

    // Vérifier les credentials
    const credentialService = window.TotleadsCredentialService;

    if (!credentialService || !credentialService.hasValidCredentials()) {
      showStatus(i18n.t('errors.missingConfig'), 'error');
      configSection.style.display = 'block';
      exportSection.style.display = 'none';
      return;
    }

    const credentials = credentialService.getCredentials();

    if (!credentials) {
      showStatus(i18n.t('errors.sessionExpired'), 'error');
      configSection.style.display = 'block';
      exportSection.style.display = 'none';
      return;
    }

    // Valider la session au tout début (fail fast) : token encore obtenable
    const token = await credentialService.getValidSanctumToken();
    if (!token) {
      showStatus(i18n.t('errors.sessionExpired'), 'error');
      configSection.style.display = 'block';
      exportSection.style.display = 'none';
      credentialService.clearCredentials();
      return;
    }

    // Si "Ajouter à une liste" est coché, exiger une liste sélectionnée
    const addToList = addToListCheckbox.checked;
    const listName = addToList ? listNameSelect.value.trim() : '';
    if (addToList && !listName) {
      showStatus(i18n.t('errors.listNameRequired'), 'error');
      listNameSelect.focus();
      return;
    }

    // Vérifier qu'on a des filtres de recherche (query params ou hash)
    const domHelpers = window.TotleadsDOMHelpers;
    if (!domHelpers || !domHelpers.hasSearchFiltersOrResults()) {
      showStatus(i18n.t('errors.applySearchFiltersFirst'), 'error');
      return;
    }

    // Lire le nombre de companies
    const maxCompanies = parseInt(maxCompaniesInput.value, 10);
    const parsedMaxLimit = parseInt(maxCompaniesInput.max, 10);
    const maxLimit = !isNaN(parsedMaxLimit) && parsedMaxLimit >= 0 ? parsedMaxLimit : 1000;

    if (maxLimit < 1) {
      showStatus(i18n.t('errors.quotaExceededCompanies', { max: maxLimit }), 'error');
      maxCompaniesInput.value = maxLimit;
      maxCompaniesInput.focus();
      return;
    }

    if (isNaN(maxCompanies) || maxCompanies < 1) {
      showStatus(i18n.t('errors.minCompaniesRequired'), 'error');
      maxCompaniesInput.focus();
      return;
    }

    if (maxCompanies > maxLimit) {
      showStatus(i18n.t('errors.quotaExceededCompanies', { max: maxLimit }), 'error');
      maxCompaniesInput.value = maxLimit;
      maxCompaniesInput.focus();
      return;
    }

    showStatus(i18n.t('status.extractionStarting'));

    try {
      // Envoyer le message d'extraction (avec option ajout à une liste)
      window.postMessage({
        type: 'LINKEDIN_EXTRACTOR',
        action: 'extractAndUpload',
        credentials: {
          secretKey: credentials.secretKey,
          maxLeads: maxCompanies
        },
        addToList: addToList,
        listName: addToList ? listName : null
      }, '*');

      // Passer en mode stop après 1 seconde
      setTimeout(() => {
        if (currentStatusInterval !== null) {
          isExtracting = true;
          extractCompaniesBtn.textContent = i18n.t('extraction.stopButton');
          extractCompaniesBtn.classList.add('stop-mode');
        }
      }, 1000);

      // Fonction pour mettre à jour le statut
      const updateStatus = async () => {
        if (!currentStatusInterval) {
          return;
        }

        try {
          const state = await chrome.runtime.sendMessage({
            action: 'getBackgroundProcessState'
          });

          if (state && state.isRunning) {
            const companiesCollected = Math.min(state.leadsCollected, state.maxLeads);
            showStatus(i18n.t('status.listExtractionProgress', { current: companiesCollected, max: state.maxLeads }), 'processing');
          } else if (state && !state.isRunning && state.leadsCollected > 0) {
            if (currentStatusInterval) {
              clearInterval(currentStatusInterval);
              currentStatusInterval = null;
            }
          }
        } catch (error) {
          // Erreur silencieuse
        }
      };

      // Première mise à jour après 500ms
      setTimeout(updateStatus, 500);

      // Puis mise à jour toutes les 2 secondes
      currentStatusInterval = setInterval(updateStatus, 2000);

      // Écouter la réponse
      const handleResponse = (event) => {
        if (event.data.type === 'LINKEDIN_EXTRACTOR_RESPONSE') {
          removeActiveResponseHandler(handleResponse);

          const response = event.data.data;

          if (response && response.success) {
            if (response.dataSource === 'BACKGROUND_PROCESS') {
              // Laisser l'intervalle continuer
            } else {
              showStatus(i18n.t('status.listExtractionCompleted', { count: response.leadsCount || 0 }), 'success');
              if (currentStatusInterval) {
                clearInterval(currentStatusInterval);
                currentStatusInterval = null;
              }
              isExtracting = false;
              extractCompaniesBtn.textContent = i18n.t('listWindow.exportToCsvButton');
              extractCompaniesBtn.classList.remove('stop-mode');
            }
          } else {
            showStatus(i18n.t('errors.validationError', { error: response.error || i18n.t('errors.unknownError') }), 'error');
            if (currentStatusInterval) {
              clearInterval(currentStatusInterval);
              currentStatusInterval = null;
            }
            isExtracting = false;
            extractCompaniesBtn.textContent = i18n.t('listWindow.exportToCsvButton');
            extractCompaniesBtn.classList.remove('stop-mode');
          }
        }
      };

      setActiveResponseHandler(handleResponse);

      // Timeout de sécurité
      activeResponseTimeout = setTimeout(() => {
        removeActiveResponseHandler(handleResponse);
        activeResponseTimeout = null;
        if (currentStatusInterval) {
          clearInterval(currentStatusInterval);
          currentStatusInterval = null;
        }
        if (isExtracting) {
          isExtracting = false;
          extractCompaniesBtn.textContent = i18n.t('listWindow.exportToCsvButton');
          extractCompaniesBtn.classList.remove('stop-mode');
          showStatus(i18n.t('errors.extractionTimeout'), 'error');
        }
      }, 300000); // 5 minutes

    } catch (error) {
      showStatus(i18n.t('errors.extractionErrorGeneric'), 'error');
      isExtracting = false;
      extractCompaniesBtn.textContent = i18n.t('listWindow.exportToCsvButton');
      extractCompaniesBtn.classList.remove('stop-mode');
    }
  });

  function showStoppedStatusForCompanies(companiesCount, companies) {
    const i18n = window.TotleadsI18n;
    const message = `
      <div style="display: flex; flex-direction: column; gap: 12px; align-items: center;">
        <div style="font-size: 16px; font-weight: 600; color: #ff9800; margin-bottom: 4px;">
          ${i18n.t('status.stopped', { leads: companiesCount })}
        </div>
        <div style="display: flex; gap: 8px; width: 100%;">
          <button id="uploadPartialCompaniesBtn" class="button" style="flex: 1; margin: 0;">
            ${i18n.t('extraction.uploadPartialButton', { count: companiesCount })}
          </button>
          <button id="cancelCompaniesExtractionBtn" class="button secondary" style="flex: 1; margin: 0;">
            ${i18n.t('extraction.cancelButton')}
          </button>
        </div>
      </div>
    `;

    showStatus(message, '', true);

    setTimeout(() => {
      const uploadBtn = document.getElementById('uploadPartialCompaniesBtn');
      const cancelBtn = document.getElementById('cancelCompaniesExtractionBtn');

      if (uploadBtn) {
        uploadBtn.addEventListener('click', async () => {
          await handlePartialCompaniesUpload(companies, companiesCount);
        });
      }

      if (cancelBtn) {
        cancelBtn.addEventListener('click', async () => {
          await handleCancelCompaniesExtraction();
        });
      }
    }, 100);
  }

  async function handlePartialCompaniesUpload(companies, companiesCount) {
    try {
      showStatus(i18n.t('status.uploadInProgress'));

      const paginationManager = window.TotleadsPaginationManager;

      if (!paginationManager) {
        showStatus(i18n.t('errors.paginationManagerUnavailable'), 'error');
        return;
      }

      const uploadResult = await paginationManager.generateAndUploadCSV(companies, companiesCount, 'account');

      if (uploadResult && uploadResult.success) {
        await showUploadSuccessForCompanies(uploadResult.data || {});
        await chrome.runtime.sendMessage({ action: 'cancelExtraction' });
      } else {
        showStatus(i18n.t('errors.uploadError', { error: uploadResult?.error || i18n.t('errors.unknownError') }), 'error');
      }
    } catch (error) {
      showStatus(i18n.t('errors.uploadError', { error: error.message }), 'error');
    }
  }

  async function handleCancelCompaniesExtraction() {
    try {
      const result = await chrome.runtime.sendMessage({ action: 'cancelExtraction' });

      if (result && result.success) {
        showStatus(i18n.t('status.extractionCancelled'), 'success');
      } else {
        showStatus(i18n.t('errors.cancelError'), 'error');
      }
    } catch (error) {
      showStatus(i18n.t('errors.cancelError'), 'error');
    }
  }

  async function showUploadSuccessForCompanies(data) {
    const i18n = window.TotleadsI18n;
    const config = window.TotleadsConfig;
    const appBaseUrl = config?.API_BASE_URL || 'https://app.totleads.com';
    const batchesUrl = `${appBaseUrl}`;

    if (currentStatusInterval) {
      clearInterval(currentStatusInterval);
      currentStatusInterval = null;
    }

    isExtracting = false;
    setButtonToStopMode(extractCompaniesBtn, false);
    extractCompaniesBtn.style.display = 'none';

    // Mettre à jour le quota
    if (data && typeof data.remaining_quota === 'number') {
      maxCompaniesInput.max = data.remaining_quota;
      maxCompaniesInput.value = Math.min(50, data.remaining_quota);
    }

    const duplicatesRemoved = data && typeof data.duplicatesRemoved === 'number' ? data.duplicatesRemoved : 0;

    // Message de succès uniquement (sans lien), comme floating-window.js
    const message = `
      <div style="display: flex; flex-direction: column; gap: 12px; align-items: center;">
        <div>
          ${i18n.t('status.uploadSuccess')}${duplicatesRemoved > 0 ? `. ${i18n.t('status.duplicatesRemoved', { count: duplicatesRemoved })}` : ''}
        </div>
      </div>
    `;

    showStatus(message, 'success', true);

    // Ajouter le bouton lien en dehors du status, comme floating-window.js
    const downloadBtn = `<a href="${batchesUrl}" target="_blank" class="download-link-btn">
      <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16" fill="none">
        <path d="M14 14H2M12 7.33333L8 11.3333M8 11.3333L4 7.33333M8 11.3333V2" stroke="white" stroke-width="1.3125" stroke-linecap="round" stroke-linejoin="round"/>
      </svg>
      <span>${i18n.t('status.viewBatches')}</span>
    </a>`;
    exportSection.insertAdjacentHTML('beforeend', downloadBtn);
    exportSection.style.display = 'block';
  }

  const handleUploadMessage = (event) => {
    if (event.source !== window) return;

    if (event.data.type === 'LINKEDIN_EXTRACTOR' && event.data.action === 'showUploadError') {
      const errorMessage = event.data.error || i18n.t('errors.unknownError');
      const credentialService = window.TotleadsCredentialService;
      const isAuthErr = credentialService?.isAuthError?.(errorMessage);
      if (isAuthErr) {
        configSection.style.display = 'block';
        exportSection.style.display = 'none';
        showStatus(i18n.t('errors.sessionExpired'), 'error');
        if (credentialService) credentialService.clearCredentials();
      } else if (errorMessage.includes('Quota') || errorMessage.includes('quota') || errorMessage.toLowerCase().includes('dépassé')) {
        showStatus(i18n.t('errors.quotaExceededMessage', { error: errorMessage }), 'error');
      } else {
        showStatus(i18n.t('errors.uploadError', { error: errorMessage }), 'error');
      }
    }

    if (event.data.type === 'LINKEDIN_EXTRACTOR' && event.data.action === 'showUploadSuccess') {
      showUploadSuccessForCompanies(event.data.data || {});
    }
  };
  window.addEventListener('message', handleUploadMessage);

  function onClose() {
    // Annuler l'extraction en cours
    chrome.runtime.sendMessage({ action: 'cancelExtraction' }).catch(() => {});
    if (currentStatusInterval) {
      clearInterval(currentStatusInterval);
      currentStatusInterval = null;
    }
    removeActiveResponseHandler();
    if (activeResponseTimeout) {
      clearTimeout(activeResponseTimeout);
      activeResponseTimeout = null;
    }
    window.removeEventListener('message', handleListsMessage);
    window.removeEventListener('message', handleUploadMessage);
    isExtracting = false;
    if (extractCompaniesBtn) {
      extractCompaniesBtn.classList.remove('stop-mode');
    }
  }

  // Bouton fermer
  closeBtn.addEventListener('click', function () {
    floatingWindow.remove();
  });

  // Clic sur "Download CSV" : ouvrir l'URL et fermer la fenêtre
  exportSection.addEventListener('click', function (e) {
    const link = e.target.closest('.download-link-btn');
    if (!link) return;
    e.preventDefault();
    window.open(link.href, '_blank');
    floatingWindow.remove();
  });

  // Améliorer l'accessibilité de la fenêtre flottante
  enhanceListFloatingWindowAccessibility(floatingWindow, { onClose });
}

/**
 * Améliore l'accessibilité de la fenêtre flottante
 * @param {HTMLElement} floatingWindow - Fenêtre flottante
 * @param {{ onClose?: () => void }} [options] - Options dont onClose appelé à la fermeture
 */
function enhanceListFloatingWindowAccessibility(floatingWindow, options = {}) {
  const a11y = window.TotleadsA11y;
  const i18n = window.TotleadsI18n;

  if (!a11y || !i18n) {
    return;
  }

  // Améliorer la visibilité du focus
  a11y.enhanceFocusVisibility();

  // Rendre la fenêtre accessible (région ARIA)
  a11y.createLandmark(floatingWindow, 'dialog', i18n.t('listWindow.title'));
  floatingWindow.setAttribute('aria-modal', 'true');

  // Trap focus dans la fenêtre (focus trap)
  const cleanupFocusTrap = a11y.trapFocus(floatingWindow);

  // Fermeture avec Échap
  const closeBtn = floatingWindow.querySelector('#closeListBtn');
  const cleanupEscape = a11y.handleModalEscape(floatingWindow, () => {
    a11y.announceToScreenReader(i18n.t('listWindow.closeButton'), 'polite');
    floatingWindow.remove();
  });

  // Rendre les boutons accessibles
  a11y.makeButtonAccessible(closeBtn, {
    label: i18n.t('listWindow.closeButton')
  });

  const saveConfigBtn = floatingWindow.querySelector('#saveListConfigBtn');
  a11y.makeButtonAccessible(saveConfigBtn, {
    label: i18n.t('config.saveButton')
  });

  const extractCompaniesBtn = floatingWindow.querySelector('#extractCompaniesBtn');
  a11y.makeButtonAccessible(extractCompaniesBtn, {
    label: i18n.t('listWindow.exportToCsvButton')
  });

  // Rendre les inputs accessibles
  const secretKeyInput = floatingWindow.querySelector('#secretKeyListInput');
  a11y.makeInputAccessible(secretKeyInput, {
    label: i18n.t('config.secretKey'),
    required: true
  });

  const listNameSelect = floatingWindow.querySelector('#listNameSelect');
  a11y.makeInputAccessible(listNameSelect, {
    label: i18n.t('listWindow.selectList'),
    required: false
  });

  const addToListCheckbox = floatingWindow.querySelector('#addToListCheckbox');
  if (addToListCheckbox) {
    a11y.makeInputAccessible(addToListCheckbox, {
      label: i18n.t('listWindow.addResultsToListLabel'),
      required: false
    });
  }

  // Nettoyer les listeners lors de la fermeture de la fenêtre
  const originalRemove = floatingWindow.remove.bind(floatingWindow);
  floatingWindow.remove = function () {
    options?.onClose?.();
    cleanupFocusTrap();
    cleanupEscape();
    originalRemove();
  };
}

// Écouter les messages du background script
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.action === 'showListWindow') {
    createListFloatingWindow();
    sendResponse({ success: true });
  }
});

// Écouter les messages postMessage de content-script pour ouvrir la fenêtre
window.addEventListener('message', (event) => {
  if (event.data.type === 'LINKEDIN_LIST_AUTOMATION' && event.data.action === 'showListWindow') {
    createListFloatingWindow();
  }
});
